//! Replays inputs captured from the real zod schemas of the TS tools
//! (`tests/data/validation-vectors.json`, generated by `tests/data/gen-validation-vectors.mts`):
//! the MCP SDK validation pass (strip) and the catalog parse (passthrough), including the exact
//! issue text.

use paseo_tools::schemas::input_schema;
use paseo_tools::zod::{issues_message, ParsePass};
use serde_json::Value;

/// `{ "$rep": { s, n } }` is a repeated string, `{ "$undefined": true }` is JS `undefined`.
fn materialize(value: &Value) -> Option<Value> {
    match value {
        Value::Object(map) if map.contains_key("$undefined") => None,
        Value::Object(map) if map.contains_key("$rep") => {
            let rep = &map["$rep"];
            Some(Value::String(
                rep["s"]
                    .as_str()
                    .unwrap()
                    .repeat(rep["n"].as_u64().unwrap() as usize),
            ))
        }
        Value::Array(items) => Some(Value::Array(items.iter().filter_map(materialize).collect())),
        Value::Object(map) => Some(Value::Object(
            map.iter()
                .filter_map(|(k, v)| materialize(v).map(|v| (k.clone(), v)))
                .collect(),
        )),
        other => Some(other.clone()),
    }
}

fn check(
    label: &str,
    actual: Result<Value, Vec<paseo_tools::zod::Issue>>,
    expected: &Value,
    prefix: &str,
    failures: &mut Vec<String>,
) {
    match (actual, expected["ok"].as_bool()) {
        (Ok(value), Some(true)) => {
            if value != expected["data"] {
                failures.push(format!("{label}: data {value} != {}", expected["data"]));
            }
        }
        (Err(issues), Some(false)) => {
            let message = format!("{prefix}{}", issues_message(&issues));
            if message != expected["message"].as_str().unwrap() {
                failures.push(format!(
                    "{label}: message\n--- got\n{message}\n--- want\n{}",
                    expected["message"].as_str().unwrap()
                ));
            }
        }
        (Ok(value), _) => failures.push(format!("{label}: accepted {value}, want {expected}")),
        (Err(issues), _) => failures.push(format!(
            "{label}: rejected ({}), want {expected}",
            issues_message(&issues)
        )),
    }
}

#[test]
fn validation_matches_zod() {
    let text = std::fs::read_to_string(concat!(
        env!("CARGO_MANIFEST_DIR"),
        "/tests/data/validation-vectors.json"
    ))
    .unwrap();
    let vectors: Vec<Value> = serde_json::from_str(&text).unwrap();
    let mut failures = Vec::new();
    let mut cases = 0;
    for entry in &vectors {
        let tool = entry["tool"].as_str().unwrap();
        let caller = entry["variant"] == "caller";
        let schema = input_schema(tool, caller).unwrap_or_else(|| panic!("no schema for {tool}"));
        for case in entry["cases"].as_array().unwrap() {
            cases += 1;
            let input = materialize(&case["input"]);
            let label = format!("{tool}[{}] {}", entry["variant"], case["input"]);
            let sdk = &case["sdk"];
            // A non-object `arguments` is rejected by the protocol layer before validation
            // (covered in paseo-mcp).
            if sdk.get("threw").is_some() {
                continue;
            }
            check(
                &format!("{label} (mcp)"),
                schema.parse(ParsePass::Mcp, input.as_ref()),
                sdk,
                &format!(
                    "MCP error -32602: Input validation error: Invalid arguments for tool {tool}: "
                ),
                &mut failures,
            );
            let catalog = if case["catalog"] == "=sdk" {
                sdk
            } else {
                &case["catalog"]
            };
            check(
                &format!("{label} (catalog)"),
                schema.parse(ParsePass::Catalog, input.as_ref()),
                catalog,
                "",
                &mut failures,
            );
        }
    }
    assert!(cases > 2000, "only {cases} cases");
    assert!(
        failures.is_empty(),
        "{} of {cases} cases differ; first {}:\n{}",
        failures.len(),
        failures.len().min(8),
        failures
            .iter()
            .take(8)
            .cloned()
            .collect::<Vec<_>>()
            .join("\n====\n")
    );
}
